CREATE OR REPLACE FUNCTION private.append_ai_creation_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event_type text;
  v_job_id uuid;
  v_proposal_id uuid;
  v_actor_id uuid;
begin
  if tg_table_name = 'ai_jobs' then
    v_event_type := 'job_created';
    v_job_id := new.id;
    v_actor_id := new.actor_id;
  elsif tg_table_name = 'ai_inputs' then
    v_event_type := 'input_added';
    v_job_id := new.job_id;
    select actor_id into v_actor_id from public.ai_jobs where id = new.job_id;
  else
    v_event_type := 'proposal_created';
    v_job_id := new.job_id;
    v_proposal_id := new.id;
    select actor_id into v_actor_id from public.ai_jobs where id = new.job_id;
    update public.ai_jobs set status = 'awaiting_confirmation' where id = new.job_id;
  end if;
  insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type)
  values (v_job_id, v_proposal_id, v_actor_id, v_event_type);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.claim_ai_action_execution(p_proposal_id uuid, p_expected_version integer, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_proposal public.ai_proposed_actions%rowtype;
  v_actor_id uuid := (select auth.uid());
begin
  if v_actor_id is null then raise exception 'authenticationRequired' using errcode = '42501'; end if;
  if p_request_id is null then raise exception 'requestIdRequired'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));

  select proposal.* into v_proposal
  from public.ai_proposed_actions proposal
  join public.ai_jobs job on job.id = proposal.job_id
  where proposal.id = p_proposal_id
    and job.actor_id = v_actor_id
    and (job.project_id is null or public.can_access_project(job.project_id))
  for update of proposal;
  if v_proposal.id is null then raise exception 'proposalNotFound' using errcode = 'P0002'; end if;
  if not private.is_ai_action_authorized(v_proposal.action_name, v_proposal.risk_level) then
    raise exception 'businessActionPermissionDenied' using errcode = '42501';
  end if;
  if v_proposal.execution_request_id = p_request_id
    and v_proposal.status in ('executing', 'executed', 'failed') then
    return jsonb_build_object('success', true, 'idempotent', true, 'status', v_proposal.status, 'version', v_proposal.version);
  end if;
  if v_proposal.status <> 'confirmed' then raise exception 'proposalNotExecutable'; end if;
  if v_proposal.version <> p_expected_version then raise exception 'proposalVersionChanged'; end if;
  if v_proposal.expires_at <= now() then
    update public.ai_proposed_actions set status = 'expired', version = version + 1 where id = v_proposal.id;
    insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type)
      values (v_proposal.job_id, v_proposal.id, v_actor_id, 'expired');
    return jsonb_build_object('success', false, 'error', 'proposalExpired', 'version', v_proposal.version + 1);
  end if;

  update public.ai_proposed_actions
  set status = 'executing', execution_request_id = p_request_id, version = version + 1
  where id = v_proposal.id
  returning * into v_proposal;
  update public.ai_jobs set status = 'executing' where id = v_proposal.job_id;
  insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type, event_payload)
    values (v_proposal.job_id, v_proposal.id, v_actor_id, 'execution_started', jsonb_build_object('request_id', p_request_id));
  return jsonb_build_object('success', true, 'idempotent', false, 'status', v_proposal.status, 'version', v_proposal.version);
end;
$function$

CREATE OR REPLACE FUNCTION private.complete_ai_action_execution(p_proposal_id uuid, p_request_id uuid, p_success boolean, p_verified boolean, p_result jsonb DEFAULT '{}'::jsonb, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_proposal public.ai_proposed_actions%rowtype;
  v_actor_id uuid := (select auth.uid());
  v_status text;
begin
  if v_actor_id is null then raise exception 'authenticationRequired' using errcode = '42501'; end if;
  if p_request_id is null then raise exception 'requestIdRequired'; end if;
  if jsonb_typeof(coalesce(p_result, '{}'::jsonb)) <> 'object' then raise exception 'executionResultMustBeObject'; end if;

  select proposal.* into v_proposal
  from public.ai_proposed_actions proposal
  join public.ai_jobs job on job.id = proposal.job_id
  where proposal.id = p_proposal_id
    and job.actor_id = v_actor_id
    and (job.project_id is null or public.can_access_project(job.project_id))
  for update of proposal;
  if v_proposal.id is null then raise exception 'proposalNotFound' using errcode = 'P0002'; end if;
  if not private.is_ai_action_authorized(v_proposal.action_name, v_proposal.risk_level) then
    raise exception 'businessActionPermissionDenied' using errcode = '42501';
  end if;
  if v_proposal.execution_request_id <> p_request_id then raise exception 'requestIdConflict'; end if;
  if v_proposal.status in ('executed', 'failed') then
    return jsonb_build_object('success', true, 'idempotent', true, 'status', v_proposal.status, 'version', v_proposal.version);
  end if;
  if v_proposal.status <> 'executing' then raise exception 'proposalNotExecuting'; end if;
  if p_success and not p_verified then raise exception 'successfulExecutionMustBeVerified'; end if;
  if not p_success and nullif(trim(coalesce(p_error, '')), '') is null then raise exception 'failedExecutionRequiresError'; end if;

  v_status := case when p_success then 'executed' else 'failed' end;
  update public.ai_proposed_actions
  set status = v_status, execution_result = coalesce(p_result, '{}'::jsonb),
      execution_error = case when p_success then null else nullif(trim(coalesce(p_error, '')), '') end,
      executed_at = now(), verified = p_verified, version = version + 1
  where id = v_proposal.id
  returning * into v_proposal;
  update public.ai_jobs job
  set status = case
        when exists (
          select 1 from public.ai_proposed_actions proposal
          where proposal.job_id = job.id and proposal.status = 'failed'
        ) then 'failed'
        when exists (
          select 1 from public.ai_proposed_actions proposal
          where proposal.job_id = job.id and proposal.status = 'executing'
        ) then 'executing'
        when exists (
          select 1 from public.ai_proposed_actions proposal
          where proposal.job_id = job.id
            and proposal.status in ('awaiting_clarification', 'proposed', 'confirmed')
        ) then 'awaiting_confirmation'
        else 'completed'
      end,
      finished_at = case when exists (
        select 1 from public.ai_proposed_actions proposal
        where proposal.job_id = job.id
          and proposal.status in ('awaiting_clarification', 'proposed', 'confirmed', 'executing')
      ) then null else now() end,
      failure_message = case when p_success then failure_message else v_proposal.execution_error end
  where job.id = v_proposal.job_id;
  insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type, event_payload)
    values (
      v_proposal.job_id, v_proposal.id, v_actor_id,
      case when p_success then 'executed' else 'failed' end,
      jsonb_build_object('verified', p_verified, 'has_error', v_proposal.execution_error is not null)
    );
  return jsonb_build_object('success', true, 'idempotent', false, 'status', v_status, 'version', v_proposal.version);
end;
$function$

CREATE OR REPLACE FUNCTION private.complete_ai_input_extraction(p_input_id uuid, p_extracted_text text, p_extraction_result jsonb, p_contains_sensitive_data boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_input public.ai_inputs%rowtype;
  v_actor_id uuid := (select auth.uid());
begin
  if v_actor_id is null then raise exception 'authenticationRequired' using errcode = '42501'; end if;
  if jsonb_typeof(coalesce(p_extraction_result, '{}'::jsonb)) <> 'object' then
    raise exception 'extractionResultMustBeObject';
  end if;
  select input.* into v_input
  from public.ai_inputs input
  join public.ai_jobs job on job.id = input.job_id
  where input.id = p_input_id
    and job.actor_id = v_actor_id
    and (job.project_id is null or public.can_access_project(job.project_id))
    and input.redacted_at is null
  for update of input;
  if v_input.id is null then raise exception 'aiInputNotFound' using errcode = 'P0002'; end if;
  if v_input.extracted_text is not null or v_input.extraction_result <> '{}'::jsonb then
    raise exception 'aiInputExtractionAlreadyCompleted';
  end if;
  update public.ai_inputs
  set extracted_text = nullif(p_extracted_text, ''),
      extraction_result = coalesce(p_extraction_result, '{}'::jsonb),
      contains_sensitive_data = coalesce(p_contains_sensitive_data, true),
      updated_at = now()
  where id = v_input.id;
  return jsonb_build_object('success', true, 'input_id', v_input.id);
end;
$function$

CREATE OR REPLACE FUNCTION private.confirm_ai_proposed_action(p_proposal_id uuid, p_expected_version integer, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_proposal public.ai_proposed_actions%rowtype;
  v_actor_id uuid := (select auth.uid());
begin
  if v_actor_id is null then raise exception 'authenticationRequired' using errcode = '42501'; end if;
  if p_request_id is null then raise exception 'requestIdRequired'; end if;

  select proposal.* into v_proposal
  from public.ai_proposed_actions proposal
  join public.ai_jobs job on job.id = proposal.job_id
  where proposal.id = p_proposal_id
    and job.actor_id = v_actor_id
    and (job.project_id is null or public.can_access_project(job.project_id))
  for update of proposal;
  if v_proposal.id is null then raise exception 'proposalNotFound' using errcode = 'P0002'; end if;
  if not private.is_ai_action_authorized(v_proposal.action_name, v_proposal.risk_level) then
    raise exception 'businessActionPermissionDenied' using errcode = '42501';
  end if;

  if v_proposal.confirmation_request_id = p_request_id
    and v_proposal.status in ('confirmed', 'executing', 'executed') then
    return jsonb_build_object('success', true, 'idempotent', true, 'version', v_proposal.version);
  end if;
  if v_proposal.status <> 'proposed' then raise exception 'proposalNotConfirmable'; end if;
  if v_proposal.version <> p_expected_version then raise exception 'proposalVersionChanged'; end if;
  if v_proposal.expires_at <= now() then
    update public.ai_proposed_actions set status = 'expired', version = version + 1 where id = v_proposal.id;
    insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type)
      values (v_proposal.job_id, v_proposal.id, v_actor_id, 'expired');
    return jsonb_build_object('success', false, 'error', 'proposalExpired', 'version', v_proposal.version + 1);
  end if;
  if v_proposal.requires_clarification then raise exception 'proposalRequiresClarification'; end if;

  update public.ai_proposed_actions
  set status = 'confirmed', confirmation_request_id = p_request_id,
      confirmed_by = v_actor_id, confirmed_at = now(), version = version + 1
  where id = v_proposal.id
  returning * into v_proposal;
  update public.ai_jobs set status = 'awaiting_confirmation' where id = v_proposal.job_id;
  insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type, event_payload)
    values (v_proposal.job_id, v_proposal.id, v_actor_id, 'confirmed', jsonb_build_object('version', v_proposal.version));
  return jsonb_build_object('success', true, 'idempotent', false, 'version', v_proposal.version);
end;
$function$

CREATE OR REPLACE FUNCTION private.operator_query_daily_booking(p_booking_id uuid DEFAULT NULL::uuid, p_building_code text DEFAULT NULL::text, p_unit_no text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_unit public.units%rowtype;
  v_building public.buildings%rowtype;
  v_booking_id uuid;
  v_active_count integer;
  v_snapshot jsonb;
begin
  if not private.current_operator_action_allowed('query_daily_booking', 'L0') then
    raise exception 'dailyReadPermissionDenied' using errcode = '42501';
  end if;

  if p_booking_id is null and (nullif(btrim(p_building_code), '') is null or nullif(btrim(p_unit_no), '') is null) then
    raise exception 'bookingSelectorRequired';
  end if;
  if p_booking_id is not null and (p_building_code is not null or p_unit_no is not null) then
    raise exception 'bookingSelectorConflict';
  end if;

  if p_booking_id is not null then
    select b.id into v_booking_id from public.daily_bookings b where b.id = p_booking_id;
    if v_booking_id is null then
      return jsonb_build_object('status', 'not_found', 'selector', jsonb_build_object('bookingId', p_booking_id));
    end if;
  else
    select u.* into v_unit
    from public.units u
    join public.buildings b on b.id = u.building_id
    where lower(b.code) = lower(btrim(p_building_code))
      and lower(u.unit_no) = lower(btrim(p_unit_no));

    if v_unit.id is null then
      return jsonb_build_object(
        'status', 'not_found',
        'selector', jsonb_build_object('buildingCode', btrim(p_building_code), 'unitNo', btrim(p_unit_no))
      );
    end if;

    select b.* into v_building from public.buildings b where b.id = v_unit.building_id;

    select count(*) into v_active_count
    from public.daily_bookings d
    where d.unit_id = v_unit.id
      and d.status in ('pending_review', 'confirmed', 'checked_in');

    select d.id into v_booking_id
    from public.daily_bookings d
    where d.unit_id = v_unit.id
      and d.status in ('pending_review', 'confirmed', 'checked_in')
    order by d.check_in desc, d.created_at desc
    limit 1;

    if v_active_count <> 1 then
      return jsonb_build_object(
        'status', case when v_active_count > 1 then 'ambiguous' else 'selection_required' end,
        'unit', to_jsonb(v_unit) || jsonb_build_object(
          'building_code', v_building.code,
          'building_name', v_building.display_name
        ),
        'candidates', coalesce((
          select jsonb_agg(jsonb_build_object(
            'bookingId', d.id,
            'status', d.status,
            'checkIn', d.check_in,
            'checkOut', d.check_out,
            'checkoutMode', d.checkout_mode,
            'guestName', d.guest_name,
            'updatedAt', d.updated_at
          ) order by d.check_in desc, d.created_at desc)
          from (
            select * from public.daily_bookings
            where unit_id = v_unit.id
            order by check_in desc, created_at desc
            limit 10
          ) d
        ), '[]'::jsonb)
      );
    end if;
  end if;

  v_snapshot := public.daily_booking_operation_snapshot(v_booking_id, null);
  return jsonb_build_object(
    'status', 'found',
    'snapshot', v_snapshot,
    'context', (
      select jsonb_build_object(
        'buildingCode', building.code,
        'buildingName', building.display_name,
        'bookingAgent', case when agent.id is null then null else jsonb_build_object('id', agent.id, 'name', agent.name) end,
        'guest', case when guest.id is null then null else jsonb_build_object('id', guest.id, 'name', guest.name) end
      )
      from public.daily_bookings booking
      join public.units unit_record on unit_record.id = booking.unit_id
      join public.buildings building on building.id = unit_record.building_id
      left join public.customers agent on agent.id = coalesce(booking.booking_agent_id, booking.customer_id)
      left join public.customers guest on guest.id = booking.guest_customer_id
      where booking.id = v_booking_id
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.redact_expired_ai_input(p_input_id uuid, p_expected_storage_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_input public.ai_inputs%rowtype;
  v_actor_id uuid := (select auth.uid());
begin
  if v_actor_id is null then raise exception 'authenticationRequired' using errcode = '42501'; end if;
  select input.* into v_input
  from public.ai_inputs input
  join public.ai_jobs job on job.id = input.job_id
  where input.id = p_input_id
    and job.actor_id = v_actor_id
    and (job.project_id is null or public.can_access_project(job.project_id))
  for update of input;
  if v_input.id is null then raise exception 'aiInputNotFound' using errcode = 'P0002'; end if;
  if v_input.redacted_at is not null then
    return jsonb_build_object('success', true, 'idempotent', true);
  end if;
  if v_input.retention_until > now() then raise exception 'aiInputRetentionNotExpired'; end if;
  if v_input.storage_path is distinct from p_expected_storage_path then raise exception 'aiInputStoragePathChanged'; end if;

  update public.ai_inputs
  set raw_text = null,
      storage_bucket = null,
      storage_path = null,
      original_filename = null,
      mime_type = null,
      file_size_bytes = null,
      extracted_text = null,
      extraction_result = jsonb_build_object('redacted', true),
      redacted_at = now()
  where id = v_input.id;
  insert into public.ai_action_events(job_id, actor_id, event_type, event_payload)
    values (v_input.job_id, v_actor_id, 'input_redacted', jsonb_build_object('input_id', v_input.id));
  return jsonb_build_object('success', true, 'idempotent', false);
end;
$function$

CREATE OR REPLACE FUNCTION private.reject_ai_proposed_action(p_proposal_id uuid, p_expected_version integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_proposal public.ai_proposed_actions%rowtype;
  v_actor_id uuid := (select auth.uid());
  v_reason text := nullif(trim(coalesce(p_reason, '')), '');
begin
  if v_actor_id is null then raise exception 'authenticationRequired' using errcode = '42501'; end if;
  if v_reason is null then raise exception 'rejectionReasonRequired'; end if;
  select proposal.* into v_proposal
  from public.ai_proposed_actions proposal
  join public.ai_jobs job on job.id = proposal.job_id
  where proposal.id = p_proposal_id
    and job.actor_id = v_actor_id
    and (job.project_id is null or public.can_access_project(job.project_id))
  for update of proposal;
  if v_proposal.id is null then raise exception 'proposalNotFound' using errcode = 'P0002'; end if;
  if v_proposal.status = 'rejected' then
    return jsonb_build_object('success', true, 'idempotent', true, 'version', v_proposal.version);
  end if;
  if v_proposal.status not in ('awaiting_clarification', 'proposed', 'confirmed') then raise exception 'proposalNotRejectable'; end if;
  if v_proposal.version <> p_expected_version then raise exception 'proposalVersionChanged'; end if;

  update public.ai_proposed_actions
  set status = 'rejected', rejected_by = v_actor_id, rejected_at = now(),
      rejection_reason = v_reason, version = version + 1
  where id = v_proposal.id
  returning * into v_proposal;
  insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type, event_payload)
    values (v_proposal.job_id, v_proposal.id, v_actor_id, 'rejected', jsonb_build_object('version', v_proposal.version));
  update public.ai_jobs job
  set status = case when exists (
        select 1 from public.ai_proposed_actions proposal
        where proposal.job_id = job.id
          and proposal.status in ('awaiting_clarification', 'proposed', 'confirmed', 'executing')
      ) then 'awaiting_confirmation' else 'completed' end,
      finished_at = case when exists (
        select 1 from public.ai_proposed_actions proposal
        where proposal.job_id = job.id
          and proposal.status in ('awaiting_clarification', 'proposed', 'confirmed', 'executing')
      ) then null else now() end
  where job.id = v_proposal.job_id;
  return jsonb_build_object('success', true, 'idempotent', false, 'version', v_proposal.version);
end;
$function$

CREATE OR REPLACE FUNCTION private.revise_ai_proposed_action(p_proposal_id uuid, p_expected_version integer, p_action_input jsonb, p_before_snapshot jsonb, p_before_versions jsonb, p_expected_effects jsonb, p_warnings jsonb, p_requires_clarification boolean, p_expires_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_proposal public.ai_proposed_actions%rowtype;
  v_actor_id uuid := (select auth.uid());
begin
  if v_actor_id is null then raise exception 'authenticationRequired' using errcode = '42501'; end if;
  if jsonb_typeof(p_action_input) <> 'object'
    or jsonb_typeof(p_before_snapshot) <> 'object'
    or jsonb_typeof(p_before_versions) <> 'object'
    or jsonb_typeof(p_expected_effects) <> 'array'
    or jsonb_typeof(p_warnings) <> 'array' then
    raise exception 'invalidProposalRevision';
  end if;
  if p_expires_at <= now() then raise exception 'proposalExpiryMustBeFuture'; end if;

  select proposal.* into v_proposal
  from public.ai_proposed_actions proposal
  join public.ai_jobs job on job.id = proposal.job_id
  where proposal.id = p_proposal_id
    and job.actor_id = v_actor_id
    and (job.project_id is null or public.can_access_project(job.project_id))
  for update of proposal;
  if v_proposal.id is null then raise exception 'proposalNotFound' using errcode = 'P0002'; end if;
  if not private.is_ai_action_authorized(v_proposal.action_name, v_proposal.risk_level) then
    raise exception 'businessActionPermissionDenied' using errcode = '42501';
  end if;
  if v_proposal.status not in ('awaiting_clarification', 'proposed') then raise exception 'proposalNotEditable'; end if;
  if v_proposal.version <> p_expected_version then raise exception 'proposalVersionChanged'; end if;

  update public.ai_proposed_actions
  set action_input = p_action_input,
      before_snapshot = p_before_snapshot,
      before_versions = p_before_versions,
      expected_effects = p_expected_effects,
      warnings = p_warnings,
      requires_clarification = p_requires_clarification,
      status = case when p_requires_clarification then 'awaiting_clarification' else 'proposed' end,
      expires_at = p_expires_at,
      version = version + 1
  where id = v_proposal.id
  returning * into v_proposal;
  insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type, event_payload)
    values (
      v_proposal.job_id, v_proposal.id, v_actor_id, 'proposal_edited',
      jsonb_build_object('version', v_proposal.version, 'requires_clarification', p_requires_clarification)
    );
  return jsonb_build_object('success', true, 'version', v_proposal.version, 'status', v_proposal.status);
end;
$function$

CREATE OR REPLACE FUNCTION private.revise_ai_proposed_action_v2(p_proposal_id uuid, p_expected_version integer, p_action_name text, p_risk_level text, p_target jsonb, p_action_input jsonb, p_before_snapshot jsonb, p_before_versions jsonb, p_expected_effects jsonb, p_warnings jsonb, p_confidence numeric, p_requires_clarification boolean, p_expires_at timestamp with time zone, p_revision_summary jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_proposal public.ai_proposed_actions%rowtype;
  v_previous_action text;
  v_previous_target jsonb;
  v_actor_id uuid := (select auth.uid());
begin
  if v_actor_id is null then raise exception 'authenticationRequired' using errcode = '42501'; end if;
  if jsonb_typeof(p_target) <> 'object'
    or jsonb_typeof(p_action_input) <> 'object'
    or jsonb_typeof(p_before_snapshot) <> 'object'
    or jsonb_typeof(p_before_versions) <> 'object'
    or jsonb_typeof(p_expected_effects) <> 'array'
    or jsonb_typeof(p_warnings) <> 'array'
    or jsonb_typeof(p_revision_summary) <> 'object' then
    raise exception 'invalidProposalRevision';
  end if;
  if p_confidence < 0 or p_confidence > 1 then raise exception 'invalidProposalConfidence'; end if;
  if p_expires_at <= now() or p_expires_at > now() + interval '1 hour' then
    raise exception 'invalidProposalExpiry';
  end if;
  if not private.is_ai_action_authorized(p_action_name, p_risk_level) then
    raise exception 'businessActionPermissionDenied' using errcode = '42501';
  end if;

  select proposal.* into v_proposal
  from public.ai_proposed_actions proposal
  join public.ai_jobs job on job.id = proposal.job_id
  where proposal.id = p_proposal_id
    and job.actor_id = v_actor_id
    and (job.project_id is null or public.can_access_project(job.project_id))
  for update of proposal;
  if v_proposal.id is null then raise exception 'proposalNotFound' using errcode = 'P0002'; end if;
  if v_proposal.status not in ('awaiting_clarification', 'proposed') then raise exception 'proposalNotEditable'; end if;
  if v_proposal.version <> p_expected_version then raise exception 'proposalVersionChanged'; end if;

  v_previous_action := v_proposal.action_name;
  v_previous_target := v_proposal.target;
  update public.ai_proposed_actions
  set action_name = p_action_name,
      risk_level = p_risk_level,
      target = p_target,
      action_input = p_action_input,
      before_snapshot = p_before_snapshot,
      before_versions = p_before_versions,
      expected_effects = p_expected_effects,
      warnings = p_warnings,
      confidence = p_confidence,
      requires_clarification = p_requires_clarification,
      status = case when p_requires_clarification then 'awaiting_clarification' else 'proposed' end,
      expires_at = p_expires_at,
      version = version + 1
  where id = v_proposal.id
  returning * into v_proposal;

  insert into public.ai_action_events(job_id, proposed_action_id, actor_id, event_type, event_payload)
  values (
    v_proposal.job_id,
    v_proposal.id,
    v_actor_id,
    'proposal_edited',
    jsonb_build_object(
      'version', v_proposal.version,
      'previous_version', p_expected_version,
      'changed_fields', coalesce(p_revision_summary->'changed_fields', '[]'::jsonb),
      'action_from', v_previous_action,
      'action_to', v_proposal.action_name,
      'target_changed', v_previous_target is distinct from v_proposal.target,
      'requires_clarification', p_requires_clarification
    )
  );
  return jsonb_build_object(
    'success', true,
    'version', v_proposal.version,
    'status', v_proposal.status,
    'action_name', v_proposal.action_name,
    'expires_at', v_proposal.expires_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION private.verify_operator_daily_payment(p_booking_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payment public.payments%rowtype;
  v_booking public.daily_bookings%rowtype;
  v_audit public.audit_logs%rowtype;
begin
  if not private.current_operator_action_allowed('record_daily_payment', 'L2') then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;

  select * into v_payment from public.payments
  where request_id = p_request_id and request_kind = 'daily_payment' and source_id = p_booking_id;
  select * into v_booking from public.daily_bookings where id = p_booking_id;
  select * into v_audit from public.audit_logs
  where actor_id = (select auth.uid())
    and entity_type = 'daily_booking'
    and entity_id = p_booking_id
    and action = 'supplementary_payment'
    and metadata->>'request_id' = p_request_id::text
  order by created_at desc limit 1;

  return jsonb_build_object(
    'verified', v_payment.id is not null and v_booking.id is not null and v_audit.id is not null,
    'payment', case when v_payment.id is null then null else to_jsonb(v_payment) end,
    'booking', case when v_booking.id is null then null else jsonb_build_object(
      'id', v_booking.id,
      'prepaidAmountXof', v_booking.prepaid_amount_xof,
      'totalAmountXof', v_booking.total_amount_xof,
      'finalAmountXof', v_booking.final_amount_xof,
      'billingStatus', v_booking.billing_status,
      'status', v_booking.status
    ) end,
    'receivables', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'amountXof', r.amount_xof, 'paidAmountXof', r.paid_amount_xof, 'status', r.status
      ) order by r.created_at desc)
      from public.receivables r
      where r.source_type = 'daily_booking' and r.source_id = p_booking_id and r.status <> 'cancelled'
    ), '[]'::jsonb),
    'audit', case when v_audit.id is null then null else jsonb_build_object(
      'id', v_audit.id, 'actorId', v_audit.actor_id, 'action', v_audit.action, 'createdAt', v_audit.created_at
    ) end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.confirm_receipt_payment(payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_room_no text := payload->>'room_no';
  v_receipt_no text := nullif(payload->>'receipt_no', '');
  v_receipt_date date := (payload->>'receipt_date')::date;
  v_amount_xof numeric := (payload->>'amount_xof')::numeric;
  v_currency text := coalesce(nullif(payload->>'currency', ''), 'XOF');
  v_period_start date := nullif(payload->>'period_start', '')::date;
  v_period_end date := nullif(payload->>'period_end', '')::date;
  v_business_type text := nullif(payload->>'business_type', '');
  v_payer_name text := nullif(payload->>'payer_name', '');
  v_notes text := nullif(payload->>'notes', '');
  v_image_path text := nullif(payload->>'image_path', '');
  v_ocr_text text := nullif(payload->>'ocr_text', '');
  v_ocr_provider text := coalesce(nullif(payload->>'ocr_provider', ''), 'manual');
  v_override_duplicate boolean := coalesce((payload->>'overrideDuplicate')::boolean, false);
  v_unit_id uuid;
  v_building_id uuid;
  v_source_type text;
  v_matched_receivable_id uuid;
  v_payment_id uuid;
  v_attachment_id uuid;
  v_payment_source_type text;
  v_payment_source_id uuid;
  v_payment_customer_id uuid;
  v_matched_source_type text;
  v_matched_source_id uuid;
  v_matched_customer_id uuid;
  v_matched_amount_xof numeric;
  v_matched_paid_xof numeric;
  v_existing record;
begin
  if public.current_user_role() not in ('admin', 'finance') then
    raise exception 'financeWritePermissionDenied' using errcode = '42501';
  end if;
  if v_room_no is null or v_receipt_date is null or coalesce(v_amount_xof, 0) <= 0 then
    raise exception 'invalidReceiptPayload';
  end if;

  select u.id, u.building_id
  into v_unit_id, v_building_id
  from public.units u
  where u.unit_no = v_room_no
    and (
      nullif(payload->>'building_id', '') is null
      or u.building_id = (payload->>'building_id')::uuid
    );
  if not found then
    return jsonb_build_object('success', false, 'error', 'Room not found: ' || v_room_no);
  end if;

  v_source_type := case v_business_type
    when 'daily_rental' then 'daily_booking'
    when 'lease_rent' then 'lease_contract'
    when 'managed_lease_rent' then 'lease_contract'
    when 'sale' then 'sale_contract'
    else 'manual'
  end;

  if v_receipt_no is not null then
    select p.id, p.payment_date, p.amount
    into v_existing
    from public.payments p
    join public.units u on u.id = p.unit_id
    where p.receipt_no = v_receipt_no
      and extract(year from p.payment_date) = extract(year from v_receipt_date)
      and u.building_id = v_building_id
    limit 1;
    if found and not v_override_duplicate then
      return jsonb_build_object(
        'success', false,
        'requiresOverride', true,
        'duplicateWarning', format(
          'Duplicate receipt %s (amount %s, date %s)',
          v_receipt_no, v_existing.amount, v_existing.payment_date
        )
      );
    end if;
  end if;

  if v_source_type <> 'manual' then
    if v_period_start is not null and v_period_end is not null then
      select id, source_id, source_type, customer_id, amount_xof, paid_amount_xof
      into v_matched_receivable_id, v_matched_source_id, v_matched_source_type,
           v_matched_customer_id, v_matched_amount_xof, v_matched_paid_xof
      from public.receivables
      where unit_id = v_unit_id
        and source_type = v_source_type
        and status not in ('paid', 'cancelled')
        and due_date between v_period_start and v_period_end
      order by due_date, created_at
      limit 1
      for update;
    end if;

    if v_matched_receivable_id is null then
      select id, source_id, source_type, customer_id, amount_xof, paid_amount_xof
      into v_matched_receivable_id, v_matched_source_id, v_matched_source_type,
           v_matched_customer_id, v_matched_amount_xof, v_matched_paid_xof
      from public.receivables
      where unit_id = v_unit_id
        and source_type = v_source_type
        and status not in ('paid', 'cancelled')
      order by abs((amount_xof - paid_amount_xof) - v_amount_xof), due_date
      limit 1
      for update;
      if v_matched_receivable_id is not null
        and abs((v_matched_amount_xof - v_matched_paid_xof) - v_amount_xof) > v_amount_xof * 0.5
      then
        v_matched_receivable_id := null;
      end if;
    end if;
  end if;

  if v_matched_receivable_id is not null then
    v_payment_source_type := v_matched_source_type;
    v_payment_source_id := v_matched_source_id;
    v_payment_customer_id := v_matched_customer_id;
    update public.receivables
    set paid_amount_xof = paid_amount_xof + v_amount_xof,
        status = case
          when paid_amount_xof + v_amount_xof >= amount_xof then 'paid'
          else 'partial'
        end,
        updated_at = now()
    where id = v_matched_receivable_id;
  else
    v_payment_source_type := v_source_type;
  end if;

  insert into public.payments (
    unit_id, customer_id, source_type, source_id, payment_date,
    amount, currency, exchange_rate_to_xof, receipt_no, notes
  )
  values (
    v_unit_id, v_payment_customer_id, v_payment_source_type, v_payment_source_id,
    v_receipt_date, v_amount_xof, v_currency, 1, v_receipt_no, v_notes
  )
  returning id into v_payment_id;

  insert into public.ledger_entries (
    building_id, unit_id, payment_id, entry_date, direction,
    category, amount_xof, description
  )
  values (
    v_building_id, v_unit_id, v_payment_id, v_receipt_date, 'income',
    coalesce(v_business_type, 'manual'), v_amount_xof,
    trim('Receipt scan: ' || coalesce(v_receipt_no, 'no receipt no') ||
      ' | ' || coalesce(v_payer_name, ''))
  );

  if v_image_path is not null then
    insert into public.attachments (
      storage_path, bucket, file_type, linked_type, linked_id, unit_id,
      customer_id, uploaded_by, ocr_text, ocr_provider, metadata
    )
    values (
      v_image_path, 'receipts', 'receipt_image', 'payment', v_payment_id,
      v_unit_id, v_payment_customer_id, auth.uid(), v_ocr_text, v_ocr_provider,
      jsonb_build_object(
        'receipt_no', v_receipt_no,
        'period_start', v_period_start,
        'period_end', v_period_end,
        'business_type', v_business_type,
        'receipt_date', v_receipt_date,
        'amount_xof', v_amount_xof
      )
    )
    returning id into v_attachment_id;
  end if;

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'receipt_scan_confirm', 'payment', v_payment_id,
    jsonb_build_object(
      'room_no', v_room_no,
      'unit_id', v_unit_id,
      'amount_xof', v_amount_xof,
      'receipt_no', v_receipt_no,
      'receipt_date', v_receipt_date,
      'business_type', v_business_type,
      'attachment_id', v_attachment_id,
      'matched_receivable_id', v_matched_receivable_id,
      'unmatched_receivable', v_matched_receivable_id is null
    )
  );

  return jsonb_build_object(
    'success', true,
    'paymentId', v_payment_id,
    'attachmentId', v_attachment_id,
    'matchedReceivableId', v_matched_receivable_id,
    'unmatchedReceivable', v_matched_receivable_id is null,
    'duplicateOverridden', v_override_duplicate
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_sale_contract_rpc(p_unit_id uuid, p_customer_id uuid, p_contract_no text, p_signed_date date, p_total_amount_xof numeric, p_payment_plan_type text, p_num_installments integer DEFAULT NULL::integer, p_transfer_date date DEFAULT NULL::date, p_agency_company text DEFAULT NULL::text, p_agent_name text DEFAULT NULL::text, p_agency_commission_xof numeric DEFAULT NULL::numeric, p_agency_commission_paid boolean DEFAULT false, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_contract_id uuid;
  v_building_id uuid;
  v_installments integer;
  v_base_amount numeric;
  v_amount numeric;
  v_due_date date;
  v_index integer;
  v_category text;
begin
  if not public.has_app_role('admin', 'rental_sales') then
    raise exception 'saleCreatePermissionDenied' using errcode = '42501';
  end if;
  if p_request_id is null then raise exception 'requestIdRequired'; end if;
  if p_unit_id is null or p_customer_id is null or p_signed_date is null
    or coalesce(p_total_amount_xof, 0) <= 0 or nullif(trim(p_contract_no), '') is null then
    raise exception 'invalidSaleContractPayload';
  end if;
  if p_payment_plan_type not in ('lump_sum', 'fixed_installment', 'flexible_installment') then
    raise exception 'invalidSalePaymentPlan';
  end if;

  select id into v_contract_id from public.sale_contracts where request_id = p_request_id;
  if v_contract_id is not null then
    return jsonb_build_object('success', true, 'contract_id', v_contract_id, 'idempotent', true);
  end if;

  perform 1 from public.units where id = p_unit_id for update;
  if not found then raise exception 'unitNotFound'; end if;
  if exists (
    select 1 from public.sale_contracts
    where unit_id = p_unit_id and status in ('draft', 'active')
  ) then
    raise exception 'unitAlreadyHasCurrentSale';
  end if;
  select building_id into v_building_id from public.units where id = p_unit_id;

  insert into public.sale_contracts(
    unit_id, customer_id, contract_no, signed_date, transfer_date,
    transfer_status, agency_company, agent_name, agency_commission_amount_xof,
    agency_commission_paid, payment_plan_type, total_amount_xof, status, request_id
  ) values (
    p_unit_id, p_customer_id, trim(p_contract_no), p_signed_date, p_transfer_date,
    'not_started', nullif(trim(coalesce(p_agency_company, '')), ''),
    nullif(trim(coalesce(p_agent_name, '')), ''), p_agency_commission_xof,
    coalesce(p_agency_commission_paid, false), p_payment_plan_type,
    p_total_amount_xof, 'active', p_request_id
  ) returning id into v_contract_id;

  if p_payment_plan_type = 'lump_sum' then
    v_installments := 1;
    v_category := 'sale_lump_sum';
  elsif p_payment_plan_type = 'fixed_installment' then
    v_installments := p_num_installments;
    v_category := 'sale_installment';
    if coalesce(v_installments, 0) < 2 or v_installments > 120 then
      raise exception 'invalidInstallmentCount';
    end if;
  else
    v_installments := 0;
    v_category := 'sale_installment';
  end if;

  if v_installments > 0 then
    v_base_amount := round(p_total_amount_xof / v_installments, 2);
    for v_index in 1..v_installments loop
      v_due_date := case when p_payment_plan_type = 'lump_sum'
        then p_signed_date
        else (p_signed_date + make_interval(months => v_index))::date end;
      v_amount := case when v_index = v_installments
        then p_total_amount_xof - v_base_amount * (v_installments - 1)
        else v_base_amount end;

      insert into public.sale_payment_schedule(
        sale_contract_id, installment_no, due_date, amount_xof, status
      ) values (
        v_contract_id, v_index, v_due_date, v_amount,
        case when v_due_date < current_date then 'overdue'::public.payment_status else 'pending'::public.payment_status end
      );

      insert into public.receivables(
        building_id, unit_id, customer_id, source_type, source_id, category,
        title, due_date, amount_xof, paid_amount_xof, status, currency
      ) values (
        v_building_id, p_unit_id, p_customer_id, 'sale_contract', v_contract_id,
        v_category,
        case when p_payment_plan_type = 'lump_sum'
          then '出售房款 ' || trim(p_contract_no)
          else format('出售分期 %s 第%s期', trim(p_contract_no), v_index) end,
        v_due_date, v_amount, 0,
        case when v_due_date < current_date then 'overdue' else 'pending' end,
        'XOF'
      );
    end loop;
  end if;

  update public.units set status = 'sold', updated_at = now() where id = p_unit_id;
  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'create', 'sale_contract', v_contract_id,
    jsonb_build_object('contract_no', trim(p_contract_no), 'payment_plan', p_payment_plan_type, 'request_id', p_request_id)
  );

  return jsonb_build_object('success', true, 'contract_id', v_contract_id, 'idempotent', false);
exception
  when unique_violation then
    if exists (select 1 from public.sale_contracts where request_id = p_request_id) then
      select id into v_contract_id from public.sale_contracts where request_id = p_request_id;
      return jsonb_build_object('success', true, 'contract_id', v_contract_id, 'idempotent', true);
    end if;
    raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_apply_discount_rpc(p_booking_id uuid, p_amount numeric, p_reason text, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking public.daily_bookings%rowtype;
  v_final numeric;
begin
  if not public.has_app_role('admin', 'front_desk', 'rental_sales') then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;
  if p_amount is null or p_amount <= 0 then raise exception 'invalidDiscountAmount'; end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'discountReasonRequired'; end if;

  select * into v_booking
  from public.daily_bookings
  where id = p_booking_id
  for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;
  if v_booking.status <> 'checked_in' then raise exception 'bookingNotCheckedIn'; end if;
  if p_amount > v_booking.total_amount_xof then raise exception 'discountExceedsGross'; end if;

  v_final := v_booking.total_amount_xof - p_amount;
  update public.daily_bookings
  set manual_discount_amount_xof = p_amount,
      manual_discount_reason = btrim(p_reason),
      final_amount_xof = v_final,
      updated_at = now()
  where id = p_booking_id;

  perform public.daily_sync_booking_finance_tx(p_booking_id);

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'apply_discount', 'daily_booking', p_booking_id,
    p_actor || jsonb_build_object('discount', p_amount, 'reason', btrim(p_reason))
  );

  return public.daily_booking_operation_snapshot(p_booking_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_booking_operation_snapshot(p_booking_id uuid, p_unit_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_booking public.daily_bookings%rowtype;
  v_unit_id uuid;
  v_unit jsonb;
begin
  if not (
    (select auth.jwt()->>'role') = 'service_role'
    or
    private.current_operator_action_allowed('query_daily_booking', 'L0')
    or private.current_operator_action_allowed('record_daily_payment', 'L2')
  ) then
    raise exception 'dailyReadPermissionDenied' using errcode = '42501';
  end if;

  select * into v_booking from public.daily_bookings where id = p_booking_id;
  v_unit_id := coalesce(v_booking.unit_id, p_unit_id);

  if v_unit_id is not null then
    select to_jsonb(u) into v_unit from public.units u where u.id = v_unit_id;
  end if;

  return jsonb_build_object(
    'booking', case when v_booking.id is null then null else to_jsonb(v_booking) end,
    'unit', coalesce(v_unit, 'null'::jsonb),
    'receivables', coalesce((
      select jsonb_agg(to_jsonb(r) order by r.due_date desc, r.created_at desc)
      from public.receivables r
      where r.source_type = 'daily_booking' and r.source_id = p_booking_id
    ), '[]'::jsonb),
    'payments', coalesce((
      select jsonb_agg(to_jsonb(p) order by p.payment_date desc, p.created_at desc)
      from public.payments p
      where p.source_type = 'daily_booking' and p.source_id = p_booking_id
    ), '[]'::jsonb),
    'cleaningTasks', coalesce((
      select jsonb_agg(to_jsonb(c) order by c.created_at desc)
      from public.cleaning_tasks c
      where c.unit_id = v_unit_id
    ), '[]'::jsonb)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_cancel_booking_rpc(p_booking_id uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking public.daily_bookings%rowtype;
  v_next_status public.unit_status;
  v_paid numeric;
begin
  if not public.has_app_role('admin', 'front_desk', 'rental_sales') then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;

  select * into v_booking
  from public.daily_bookings
  where id = p_booking_id
  for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;
  if v_booking.status not in ('pending_review', 'confirmed') then
    raise exception 'bookingCannotBeCancelled';
  end if;

  select coalesce(sum(amount), 0) into v_paid
  from public.payments
  where source_type = 'daily_booking' and source_id = p_booking_id;
  if v_paid <> 0 then raise exception 'bookingHasPayments'; end if;

  update public.daily_bookings
  set status = 'cancelled',
      prepaid_amount_xof = 0,
      billing_status = 'need_top_up',
      updated_at = now()
  where id = p_booking_id;

  update public.receivables
  set status = 'cancelled', updated_at = now()
  where source_type = 'daily_booking' and source_id = p_booking_id;

  v_next_status := public.daily_resolve_unit_status(v_booking.unit_id, p_booking_id);
  update public.units
  set status = v_next_status, updated_at = now()
  where id = v_booking.unit_id;

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'cancel', 'daily_booking', p_booking_id,
    p_actor || jsonb_build_object('next_status', v_next_status)
  );

  return public.daily_booking_operation_snapshot(p_booking_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_check_in_booking_rpc(p_booking_id uuid, p_prepaid_amount numeric DEFAULT 0, p_request_id uuid DEFAULT NULL::uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking public.daily_bookings%rowtype;
  v_unit public.units%rowtype;
  v_paid numeric;
  v_final numeric;
  v_payment_id uuid;
  v_existing_booking_id uuid;
  v_existing_kind text;
begin
  if not public.has_app_role('admin', 'front_desk', 'rental_sales') then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;
  if coalesce(p_prepaid_amount, 0) < 0 then raise exception 'invalidPaymentAmount'; end if;
  if coalesce(p_prepaid_amount, 0) > 0 and p_request_id is null then
    raise exception 'requestIdRequired';
  end if;

  if p_request_id is not null then
    perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
    select source_id, request_kind
      into v_existing_booking_id, v_existing_kind
    from public.payments
    where request_id = p_request_id;
    if v_existing_booking_id is not null then
      if v_existing_booking_id <> p_booking_id or v_existing_kind is distinct from 'daily_check_in' then
        raise exception 'requestIdConflict';
      end if;
      return public.daily_booking_operation_snapshot(p_booking_id, null);
    end if;
  end if;

  select * into v_booking
  from public.daily_bookings
  where id = p_booking_id
  for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;
  if v_booking.status <> 'confirmed' then raise exception 'bookingNotConfirmed'; end if;

  select * into v_unit
  from public.units
  where id = v_booking.unit_id
  for update;
  if v_unit.status in ('maintenance', 'locked', 'sold', 'leased') then
    raise exception 'unitUnavailable';
  end if;
  if exists (
    select 1 from public.cleaning_tasks
    where unit_id = v_booking.unit_id and is_completed = false
  ) then raise exception 'cleaningPending'; end if;
  if exists (
    select 1 from public.daily_bookings
    where unit_id = v_booking.unit_id and status = 'checked_in' and id <> p_booking_id
  ) then raise exception 'unitAlreadyOccupied'; end if;

  select coalesce(sum(amount), 0) into v_paid
  from public.payments
  where source_type = 'daily_booking' and source_id = p_booking_id;
  v_final := greatest(0, coalesce(v_booking.final_amount_xof, v_booking.total_amount_xof, 0));
  if v_paid + coalesce(p_prepaid_amount, 0) > v_final then
    raise exception 'paymentExceedsOutstanding';
  end if;

  update public.daily_bookings
  set status = 'checked_in', updated_at = now()
  where id = p_booking_id;

  update public.units
  set status = 'daily_occupied', updated_at = now()
  where id = v_booking.unit_id;

  if coalesce(p_prepaid_amount, 0) > 0 then
    insert into public.payments(
      customer_id, unit_id, source_type, source_id, payment_date,
      amount, currency, exchange_rate_to_xof, request_id, request_kind
    )
    values (
      v_booking.customer_id, v_booking.unit_id, 'daily_booking', p_booking_id, current_date,
      p_prepaid_amount, 'XOF', 1, p_request_id, 'daily_check_in'
    )
    returning id into v_payment_id;

    insert into public.ledger_entries(
      building_id, unit_id, payment_id, entry_date, direction, category, amount_xof, description
    )
    values (
      v_unit.building_id, v_booking.unit_id, v_payment_id, current_date,
      'income', 'daily_rental', p_prepaid_amount, '日租预付 房间' || v_unit.unit_no
    );
  end if;

  perform public.daily_sync_booking_finance_tx(p_booking_id);

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'check_in', 'daily_booking', p_booking_id,
    p_actor || jsonb_build_object(
      'prepaid_amount', coalesce(p_prepaid_amount, 0),
      'request_id', p_request_id
    )
  );

  return public.daily_booking_operation_snapshot(p_booking_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_check_out_booking_rpc(p_booking_id uuid, p_actual_check_out date DEFAULT CURRENT_DATE, p_final_amount numeric DEFAULT NULL::numeric, p_discount_amount numeric DEFAULT 0, p_discount_reason text DEFAULT NULL::text, p_checkout_unit_status unit_status DEFAULT 'cleaning_pending'::unit_status, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking public.daily_bookings%rowtype;
  v_nights integer;
  v_gross numeric;
  v_discount numeric;
  v_final numeric;
  v_paid numeric;
begin
  if not public.has_app_role('admin', 'front_desk', 'rental_sales') then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;

  select * into v_booking
  from public.daily_bookings
  where id = p_booking_id
  for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;
  if v_booking.status <> 'checked_in' then raise exception 'bookingNotCheckedIn'; end if;
  if p_actual_check_out < v_booking.check_in then raise exception 'actualCheckOutBeforeCheckIn'; end if;
  if p_checkout_unit_status <> 'cleaning_pending' then
    raise exception 'checkoutMustCreateCleaning';
  end if;

  v_nights := greatest(1, p_actual_check_out - v_booking.check_in);
  v_gross := round(v_nights * v_booking.nightly_price_xof);
  v_discount := greatest(0, coalesce(p_discount_amount, 0));
  if v_discount > 0 and nullif(btrim(p_discount_reason), '') is null then
    raise exception 'discountReasonRequired';
  end if;
  if v_discount > v_gross then raise exception 'discountExceedsGross'; end if;
  v_final := v_gross - v_discount;
  if p_final_amount is not null and p_final_amount <> v_final then
    raise exception 'finalAmountMustMatchCalculatedAmount';
  end if;

  select coalesce(sum(amount), 0) into v_paid
  from public.payments
  where source_type = 'daily_booking' and source_id = p_booking_id;

  update public.daily_bookings
  set status = 'checked_out',
      check_out = case when checkout_mode = 'open' then p_actual_check_out else check_out end,
      actual_check_out = p_actual_check_out,
      total_amount_xof = v_gross,
      final_amount_xof = v_final,
      manual_discount_amount_xof = v_discount,
      manual_discount_reason = case when v_discount > 0 then btrim(p_discount_reason) else null end,
      updated_at = now()
  where id = p_booking_id;

  update public.units
  set status = 'cleaning_pending', updated_at = now()
  where id = v_booking.unit_id;

  if not exists (
    select 1 from public.cleaning_tasks
    where daily_booking_id = p_booking_id and is_completed = false
  ) then
    insert into public.cleaning_tasks(unit_id, daily_booking_id, is_completed)
    values (v_booking.unit_id, p_booking_id, false);
  end if;

  perform public.daily_sync_booking_finance_tx(p_booking_id);

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'check_out', 'daily_booking', p_booking_id,
    p_actor || jsonb_build_object(
      'actual_check_out', p_actual_check_out,
      'nights', v_nights,
      'gross_amount', v_gross,
      'discount', v_discount,
      'final_amount', v_final,
      'paid_amount', v_paid,
      'outstanding_amount', greatest(0, v_final - v_paid)
    )
  );

  return public.daily_booking_operation_snapshot(p_booking_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_complete_cleaning_rpc(p_task_id uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_task cleaning_tasks%rowtype;
  v_next_status public.unit_status;
begin
  select * into v_task from public.cleaning_tasks where id = p_task_id for update;
  if v_task.id is null then raise exception 'cleaningTaskNotFound'; end if;
  if v_task.is_completed then raise exception 'cleaningTaskAlreadyCompleted'; end if;

  update public.cleaning_tasks set is_completed = true, completed_at = now() where id = p_task_id;
  v_next_status := public.daily_resolve_unit_status(v_task.unit_id);
  update public.units set status = v_next_status, updated_at = now() where id = v_task.unit_id;
  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values ((p_actor->>'actor_id')::uuid, 'complete_cleaning', 'cleaning_task', p_task_id,
    p_actor || jsonb_build_object('unit_id', v_task.unit_id, 'next_status', v_next_status));

  return public.daily_booking_operation_snapshot(v_task.daily_booking_id, v_task.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_confirm_booking_rpc(p_booking_id uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking daily_bookings%rowtype;
begin
  select * into v_booking from public.daily_bookings where id = p_booking_id for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;
  if v_booking.status <> 'pending_review' then raise exception 'bookingNotPendingReview'; end if;

  update public.daily_bookings set status = 'confirmed', updated_at = now() where id = p_booking_id;
  update public.units set status = 'reserved', updated_at = now() where id = v_booking.unit_id;
  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values ((p_actor->>'actor_id')::uuid, 'confirm', 'daily_booking', p_booking_id, p_actor);

  return public.daily_booking_operation_snapshot(p_booking_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_create_booking_core_rpc(p_unit_id uuid, p_customer_id uuid, p_check_in date, p_check_out date DEFAULT NULL::date, p_checkout_mode text DEFAULT 'fixed'::text, p_nightly_price_xof numeric DEFAULT 40000, p_notes text DEFAULT NULL::text, p_ota_source text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_unit units%rowtype;
  v_booking daily_bookings%rowtype;
  v_existing_booking_id uuid;
  v_building_code text;
  v_customer_blacklisted boolean;
  v_effective_check_out date;
  v_conflicting_booking daily_bookings%rowtype;
  v_nights integer;
  v_total numeric;
  v_next_status public.unit_status;
begin
  if p_request_id is null then
    raise exception 'requestIdRequired';
  end if;
  if p_check_in is null then
    raise exception 'checkInRequired';
  end if;
  if p_check_in < current_date then
    raise exception 'pastDateNotAllowed';
  end if;
  if p_checkout_mode not in ('fixed', 'open') then
    raise exception 'invalidCheckoutMode';
  end if;
  if p_checkout_mode = 'fixed' and (p_check_out is null or p_check_out <= p_check_in) then
    raise exception 'invalidDateRange';
  end if;
  if p_nightly_price_xof is null or p_nightly_price_xof <= 0 then
    raise exception 'invalidPrice';
  end if;

  -- Serialize retries that carry the same request id, including retries that
  -- accidentally target a different room because the client state changed.
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));

  -- Serialize all creates for the same room. This closes the race between
  -- checking availability and inserting the booking.
  select *
    into v_unit
  from public.units
  where id = p_unit_id
  for update;

  if v_unit.id is null then
    raise exception 'unitNotFound';
  end if;

  -- A retry with the same request id returns the already committed booking.
  select id
    into v_existing_booking_id
  from public.daily_bookings
  where creation_request_id = p_request_id;

  if v_existing_booking_id is not null then
    return public.daily_booking_operation_snapshot(v_existing_booking_id, p_unit_id);
  end if;

  select code
    into v_building_code
  from public.buildings
  where id = v_unit.building_id;

  if v_building_code is distinct from 'SACSI11' then
    raise exception 'dailyRentalOnlyAllowedInSacsi11';
  end if;

  if v_unit.status = 'maintenance' then raise exception 'unitMaintenance'; end if;
  if v_unit.status = 'locked' then raise exception 'unitLocked'; end if;
  if v_unit.status = 'sold' then raise exception 'saleConflict'; end if;
  if v_unit.status = 'leased' then raise exception 'longLeaseConflict'; end if;

  select is_blacklisted
    into v_customer_blacklisted
  from public.customers
  where id = p_customer_id;

  if not found then
    raise exception 'customerNotFound';
  end if;
  if v_customer_blacklisted then
    raise exception 'customerBlacklisted';
  end if;

  v_effective_check_out := case
    when p_checkout_mode = 'open' then date '9999-12-31'
    else p_check_out
  end;

  select *
    into v_conflicting_booking
  from public.daily_bookings b
  where b.unit_id = p_unit_id
    and b.status in ('pending_review', 'confirmed', 'checked_in')
    and b.check_in < v_effective_check_out
    and p_check_in < case
      when b.checkout_mode = 'open' then date '9999-12-31'
      else coalesce(b.check_out, b.check_in)
    end
  order by b.check_in
  limit 1;

  if v_conflicting_booking.id is not null then
    raise exception 'doubleBooked: % -> %',
      v_conflicting_booking.check_in,
      case
        when v_conflicting_booking.checkout_mode = 'open' then '?'
        else coalesce(v_conflicting_booking.check_out::text, '?')
      end;
  end if;

  if exists (
    select 1
    from public.lease_contracts l
    where l.unit_id = p_unit_id
      and l.status = 'active'
      and l.start_date < v_effective_check_out
      and l.expected_end_date > p_check_in
  ) then
    raise exception 'longLeaseConflict';
  end if;

  if exists (
    select 1
    from public.sale_contracts s
    where s.unit_id = p_unit_id
      and s.status = 'active'
  ) then
    raise exception 'saleConflict';
  end if;

  v_nights := case
    when p_checkout_mode = 'fixed' then greatest(1, p_check_out - p_check_in)
    else 1
  end;
  v_total := round(p_nightly_price_xof * v_nights);

  insert into public.daily_bookings(
    unit_id,
    customer_id,
    check_in,
    check_out,
    checkout_mode,
    nightly_price_xof,
    total_amount_xof,
    final_amount_xof,
    prepaid_amount_xof,
    billing_status,
    status,
    ota_source,
    notes,
    creation_request_id
  )
  values (
    p_unit_id,
    p_customer_id,
    p_check_in,
    case when p_checkout_mode = 'fixed' then p_check_out else null end,
    p_checkout_mode,
    p_nightly_price_xof,
    v_total,
    v_total,
    0,
    'need_top_up',
    'pending_review',
    p_ota_source,
    p_notes,
    p_request_id
  )
  returning * into v_booking;

  insert into public.receivables(
    building_id,
    unit_id,
    customer_id,
    source_type,
    source_id,
    category,
    title,
    due_date,
    amount_xof,
    paid_amount_xof,
    status,
    currency
  )
  values (
    v_unit.building_id,
    p_unit_id,
    p_customer_id,
    'daily_booking',
    v_booking.id,
    'daily_rental',
    '日租 ' || p_check_in,
    p_check_in,
    v_total,
    0,
    'pending',
    'XOF'
  );

  v_next_status := public.daily_resolve_unit_status(p_unit_id);
  update public.units
  set status = v_next_status,
      updated_at = now()
  where id = p_unit_id;

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    (p_actor->>'actor_id')::uuid,
    'create',
    'daily_booking',
    v_booking.id,
    p_actor || jsonb_build_object(
      'unit_id', p_unit_id,
      'customer_id', p_customer_id,
      'check_in', p_check_in,
      'check_out', p_check_out,
      'checkout_mode', p_checkout_mode,
      'request_id', p_request_id
    )
  );

  return public.daily_booking_operation_snapshot(v_booking.id, p_unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_create_booking_rpc(p_unit_id uuid, p_customer_id uuid, p_check_in date, p_check_out date DEFAULT NULL::date, p_checkout_mode text DEFAULT 'fixed'::text, p_nightly_price_xof numeric DEFAULT 40000, p_notes text DEFAULT NULL::text, p_ota_source text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid, p_actor jsonb DEFAULT '{}'::jsonb)
