    p_checkout_mode,
    p_nightly_price_xof,
    v_total,
    v_total,
    0,
    'need_top_up',
    'pending_review',
    p_ota_source,
    p_notes,
    p_request_id
  )
  returning * into v_booking;

  insert into public.receivables(
    building_id,
    unit_id,
    customer_id,
    source_type,
    source_id,
    category,
    title,
    due_date,
    amount_xof,
    paid_amount_xof,
    status,
    currency
  )
  values (
    v_unit.building_id,
    p_unit_id,
    p_customer_id,
    'daily_booking',
    v_booking.id,
    'daily_rental',
    '日租 ' || p_check_in,
    p_check_in,
    v_total,
    0,
    'pending',
    'XOF'
  );

  v_next_status := public.daily_resolve_unit_status(p_unit_id);
  update public.units
  set status = v_next_status,
      updated_at = now()
  where id = p_unit_id;

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    (p_actor->>'actor_id')::uuid,
    'create',
    'daily_booking',
    v_booking.id,
    p_actor || jsonb_build_object(
      'unit_id', p_unit_id,
      'customer_id', p_customer_id,
      'check_in', p_check_in,
      'check_out', p_check_out,
      'checkout_mode', p_checkout_mode,
      'request_id', p_request_id
    )
  );

  return public.daily_booking_operation_snapshot(v_booking.id, p_unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_extend_stay_rpc(p_booking_id uuid, p_new_check_out date DEFAULT NULL::date, p_extra_nights integer DEFAULT 0, p_request_id uuid DEFAULT NULL::uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking public.daily_bookings%rowtype;
  v_nights integer;
  v_total numeric;
  v_existing_request public.daily_operation_requests%rowtype;
  v_request_payload jsonb;
begin
  if not public.has_app_role('admin', 'front_desk', 'rental_sales') then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;
  if p_request_id is null then raise exception 'requestIdRequired'; end if;

  v_request_payload := jsonb_build_object(
    'new_check_out', p_new_check_out,
    'extra_nights', p_extra_nights
  );
  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
  select * into v_existing_request
  from public.daily_operation_requests
  where request_id = p_request_id;
  if v_existing_request.request_id is not null then
    if v_existing_request.operation_kind <> 'extend_stay'
      or v_existing_request.booking_id <> p_booking_id
      or v_existing_request.payload <> v_request_payload then
      raise exception 'requestIdConflict';
    end if;
    return public.daily_booking_operation_snapshot(p_booking_id, null);
  end if;

  select * into v_booking
  from public.daily_bookings
  where id = p_booking_id
  for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;
  if v_booking.status <> 'checked_in' then raise exception 'bookingNotCheckedIn'; end if;

  insert into public.daily_operation_requests(request_id, operation_kind, booking_id, payload)
  values (p_request_id, 'extend_stay', p_booking_id, v_request_payload);

  if v_booking.checkout_mode = 'fixed' then
    if p_new_check_out is null or v_booking.check_out is null or p_new_check_out <= v_booking.check_out then
      raise exception 'newCheckOutMustBeLater';
    end if;
    if exists (
      select 1 from public.daily_bookings b
      where b.unit_id = v_booking.unit_id
        and b.id <> p_booking_id
        and b.status in ('pending_review', 'confirmed', 'checked_in')
        and b.check_in < p_new_check_out
        and v_booking.check_in < case
          when b.checkout_mode = 'open' then date '9999-12-31'
          else coalesce(b.check_out, b.check_in)
        end
    ) then raise exception 'doubleBooked'; end if;
    v_nights := greatest(1, p_new_check_out - v_booking.check_in);
    v_total := round(v_nights * v_booking.nightly_price_xof);
    update public.daily_bookings
    set check_out = p_new_check_out,
        total_amount_xof = v_total,
        final_amount_xof = greatest(0, v_total - coalesce(manual_discount_amount_xof, 0)),
        updated_at = now()
    where id = p_booking_id;
  else
    if coalesce(p_extra_nights, 0) <= 0 then raise exception 'invalidExtensionNights'; end if;
    v_nights := p_extra_nights;
    v_total := v_booking.total_amount_xof + round(p_extra_nights * v_booking.nightly_price_xof);
    update public.daily_bookings
    set total_amount_xof = v_total,
        final_amount_xof = greatest(0, v_total - coalesce(manual_discount_amount_xof, 0)),
        updated_at = now()
    where id = p_booking_id;
  end if;

  perform public.daily_sync_booking_finance_tx(p_booking_id);

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'extend_stay', 'daily_booking', p_booking_id,
    p_actor || jsonb_build_object(
      'new_check_out', p_new_check_out,
      'extra_nights', v_nights,
      'new_total', v_total
    )
  );

  return public.daily_booking_operation_snapshot(p_booking_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_record_payment_rpc(p_booking_id uuid, p_amount numeric, p_payment_date date DEFAULT CURRENT_DATE, p_receipt_no text DEFAULT NULL::text, p_request_id uuid DEFAULT NULL::uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_booking public.daily_bookings%rowtype;
  v_unit public.units%rowtype;
  v_paid numeric;
  v_final numeric;
  v_payment_id uuid;
  v_existing_booking_id uuid;
  v_existing_kind text;
  v_nights integer;
  v_before jsonb;
  v_after jsonb;
  v_audit_metadata jsonb;
begin
  if not (
    (select auth.jwt()->>'role') = 'service_role'
    or private.current_operator_action_allowed('record_daily_payment', 'L2')
  ) then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;
  if p_amount is null or p_amount <= 0 or trunc(p_amount) <> p_amount then
    raise exception 'invalidPaymentAmount';
  end if;
  if p_request_id is null then raise exception 'requestIdRequired'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
  select source_id, request_kind into v_existing_booking_id, v_existing_kind
  from public.payments where request_id = p_request_id;
  if v_existing_booking_id is not null then
    if v_existing_booking_id <> p_booking_id or v_existing_kind is distinct from 'daily_payment' then
      raise exception 'requestIdConflict';
    end if;
    return public.daily_booking_operation_snapshot(p_booking_id, null);
  end if;

  select * into v_booking from public.daily_bookings where id = p_booking_id for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;
  if v_booking.status not in ('pending_review', 'confirmed', 'checked_in', 'checked_out') then
    raise exception 'bookingNotPayable';
  end if;

  v_before := jsonb_build_object(
    'prepaid_amount_xof', v_booking.prepaid_amount_xof,
    'total_amount_xof', v_booking.total_amount_xof,
    'final_amount_xof', v_booking.final_amount_xof,
    'billing_status', v_booking.billing_status
  );

  -- Running open stays accrue through today before the overpayment check.
  if coalesce(v_booking.checkout_mode, 'fixed') = 'open'
    and v_booking.status = 'checked_in'
    and v_booking.actual_check_out is null then
    v_nights := greatest(1, current_date - v_booking.check_in);
    update public.daily_bookings
    set total_amount_xof = v_nights * nightly_price_xof,
        final_amount_xof = greatest(0, v_nights * nightly_price_xof - coalesce(manual_discount_amount_xof, 0)),
        updated_at = now()
    where id = p_booking_id
    returning * into v_booking;
  end if;

  select * into v_unit from public.units where id = v_booking.unit_id;
  select coalesce(sum(amount), 0) into v_paid
  from public.payments where source_type = 'daily_booking' and source_id = p_booking_id;
  v_final := greatest(0, coalesce(v_booking.final_amount_xof, v_booking.total_amount_xof, 0));
  if v_paid + p_amount > v_final then raise exception 'paymentExceedsOutstanding'; end if;

  insert into public.payments(
    customer_id, unit_id, source_type, source_id, payment_date,
    amount, currency, exchange_rate_to_xof, receipt_no, request_id, request_kind
  ) values (
    v_booking.customer_id, v_booking.unit_id, 'daily_booking', p_booking_id,
    coalesce(p_payment_date, current_date), p_amount, 'XOF', 1,
    nullif(btrim(p_receipt_no), ''), p_request_id, 'daily_payment'
  ) returning id into v_payment_id;

  insert into public.ledger_entries(
    building_id, unit_id, payment_id, entry_date, direction, category, amount_xof, description
  ) values (
    v_unit.building_id, v_booking.unit_id, v_payment_id,
    coalesce(p_payment_date, current_date), 'income', 'daily_rental', p_amount,
    '日租收款 房间' || v_unit.unit_no
  );

  perform public.daily_sync_booking_finance_tx(p_booking_id);
  select to_jsonb(b) into v_after from public.daily_bookings b where b.id = p_booking_id;

  v_audit_metadata := jsonb_build_object(
    'payment_id', v_payment_id,
    'amount', p_amount,
    'payment_date', coalesce(p_payment_date, current_date),
    'request_id', p_request_id,
    'booking_status_at_payment', v_booking.status,
    'channel', left(coalesce(p_actor->>'channel', 'sacsi_web'), 40),
    'connector_version', left(coalesce(p_actor->>'connector_version', ''), 80),
    'protocol_version', left(coalesce(p_actor->>'protocol_version', ''), 40),
    'input_source', left(coalesce(p_actor->>'input_source', 'manual_form'), 40),
    'original_instruction', left(coalesce(p_actor->>'original_instruction', ''), 4000)
  );

  insert into public.audit_logs(
    actor_id, actor_email, actor_role, action, entity_type, entity_id,
    entity_label, before_data, after_data, metadata
  ) values (
    (select auth.uid()), left(coalesce((select auth.jwt()->>'email'), ''), 320), public.current_user_role(),
    'supplementary_payment', 'daily_booking', p_booking_id,
    v_unit.code, v_before,
    jsonb_build_object(
      'prepaid_amount_xof', v_after->'prepaid_amount_xof',
      'total_amount_xof', v_after->'total_amount_xof',
      'final_amount_xof', v_after->'final_amount_xof',
      'billing_status', v_after->'billing_status'
    ),
    v_audit_metadata
  );

  return public.daily_booking_operation_snapshot(p_booking_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_resolve_unit_status(p_unit_id uuid, p_exclude_booking_id uuid DEFAULT NULL::uuid)
 RETURNS unit_status
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current public.unit_status;
begin
  select status into v_current from public.units where id = p_unit_id;
  if v_current in ('maintenance', 'locked') then
    return v_current;
  end if;

  if exists (select 1 from public.sale_contracts where unit_id = p_unit_id and status = 'active') then
    return 'sold';
  end if;
  if exists (select 1 from public.lease_contracts where unit_id = p_unit_id and status = 'active') then
    return 'leased';
  end if;
  if exists (
    select 1 from public.daily_bookings
    where unit_id = p_unit_id and status = 'checked_in'
      and (p_exclude_booking_id is null or id <> p_exclude_booking_id)
  ) then
    return 'daily_occupied';
  end if;
  if exists (select 1 from public.cleaning_tasks where unit_id = p_unit_id and is_completed = false) then
    return 'cleaning_pending';
  end if;
  if exists (
    select 1 from public.daily_bookings
    where unit_id = p_unit_id and status in ('pending_review', 'confirmed')
      and (p_exclude_booking_id is null or id <> p_exclude_booking_id)
  ) then
    return 'reserved';
  end if;
  return 'available';
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_reverse_payment_rpc(p_payment_id uuid, p_reason text, p_request_id uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_payment public.payments%rowtype;
  v_booking public.daily_bookings%rowtype;
  v_unit public.units%rowtype;
  v_reversal_id uuid;
  v_existing_booking_id uuid;
  v_existing_kind text;
  v_existing_reversal_target uuid;
begin
  if not public.has_app_role('admin', 'front_desk', 'rental_sales') then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;
  if nullif(btrim(p_reason), '') is null then raise exception 'reversalReasonRequired'; end if;
  if p_request_id is null then raise exception 'requestIdRequired'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));
  select source_id, request_kind, reversal_of_payment_id
    into v_existing_booking_id, v_existing_kind, v_existing_reversal_target
  from public.payments
  where request_id = p_request_id;
  if v_existing_booking_id is not null then
    if v_existing_kind is distinct from 'daily_reversal'
      or v_existing_reversal_target is distinct from p_payment_id then
      raise exception 'requestIdConflict';
    end if;
    return public.daily_booking_operation_snapshot(v_existing_booking_id, null);
  end if;

  select * into v_payment
  from public.payments
  where id = p_payment_id
  for update;
  if v_payment.id is null then raise exception 'paymentNotFound'; end if;
  if v_payment.source_type <> 'daily_booking' or v_payment.source_id is null then
    raise exception 'paymentNotDailyRental';
  end if;
  if v_payment.amount <= 0 or v_payment.reversal_of_payment_id is not null then
    raise exception 'paymentCannotBeReversed';
  end if;
  if exists (
    select 1 from public.payments where reversal_of_payment_id = p_payment_id
  ) then raise exception 'paymentAlreadyReversed'; end if;

  select * into v_booking
  from public.daily_bookings
  where id = v_payment.source_id
  for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;

  select * into v_unit from public.units where id = v_booking.unit_id;

  insert into public.payments(
    customer_id, unit_id, source_type, source_id, payment_date,
    amount, currency, exchange_rate_to_xof, receipt_no, notes,
    request_id, request_kind, reversal_of_payment_id, reversal_reason
  )
  values (
    v_payment.customer_id, v_payment.unit_id, 'daily_booking', v_payment.source_id,
    current_date, -v_payment.amount, 'XOF', 1,
    'REV-' || left(v_payment.id::text, 8),
    '冲销原收款：' || btrim(p_reason),
    p_request_id, 'daily_reversal', p_payment_id, btrim(p_reason)
  )
  returning id into v_reversal_id;

  insert into public.ledger_entries(
    building_id, unit_id, payment_id, entry_date, direction, category, amount_xof, description
  )
  values (
    v_unit.building_id, v_booking.unit_id, v_reversal_id, current_date,
    'expense', 'daily_rental', v_payment.amount,
    '冲销日租收款 房间' || v_unit.unit_no || '：' || btrim(p_reason)
  );

  perform public.daily_sync_booking_finance_tx(v_payment.source_id);

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'payment_reversed', 'payment', p_payment_id,
    p_actor || jsonb_build_object(
      'booking_id', v_payment.source_id,
      'reversal_payment_id', v_reversal_id,
      'amount', v_payment.amount,
      'reason', btrim(p_reason),
      'request_id', p_request_id
    )
  );

  return public.daily_booking_operation_snapshot(v_payment.source_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.daily_set_fixed_checkout_rpc(p_booking_id uuid, p_new_check_out date, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_booking public.daily_bookings%rowtype;
  v_nights integer;
  v_total numeric;
begin
  if not public.has_app_role('admin', 'front_desk', 'rental_sales') then
    raise exception 'dailyWritePermissionDenied' using errcode = '42501';
  end if;

  select * into v_booking
  from public.daily_bookings
  where id = p_booking_id
  for update;
  if v_booking.id is null then raise exception 'bookingNotFound'; end if;
  if v_booking.status <> 'checked_in' then raise exception 'bookingNotCheckedIn'; end if;
  if v_booking.checkout_mode <> 'open' then raise exception 'bookingNotOpenEnded'; end if;
  if p_new_check_out <= v_booking.check_in then raise exception 'invalidDateRange'; end if;

  if exists (
    select 1 from public.daily_bookings b
    where b.unit_id = v_booking.unit_id
      and b.id <> p_booking_id
      and b.status in ('pending_review', 'confirmed', 'checked_in')
      and b.check_in < p_new_check_out
      and v_booking.check_in < case
        when b.checkout_mode = 'open' then date '9999-12-31'
        else coalesce(b.check_out, b.check_in)
      end
  ) then raise exception 'doubleBooked'; end if;

  v_nights := greatest(1, p_new_check_out - v_booking.check_in);
  v_total := round(v_nights * v_booking.nightly_price_xof);

  update public.daily_bookings
  set checkout_mode = 'fixed',
      check_out = p_new_check_out,
      actual_check_out = null,
      total_amount_xof = v_total,
      final_amount_xof = greatest(0, v_total - coalesce(manual_discount_amount_xof, 0)),
      updated_at = now()
  where id = p_booking_id;

  perform public.daily_sync_booking_finance_tx(p_booking_id);

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    auth.uid(), 'set_fixed_checkout', 'daily_booking', p_booking_id,
    p_actor || jsonb_build_object(
      'previous_mode', 'open',
      'new_check_out', p_new_check_out,
      'nights', v_nights,
      'new_total', v_total
    )
  );

  return public.daily_booking_operation_snapshot(p_booking_id, v_booking.unit_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_daily_booking_sacsi11_unit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (
    select 1
    from public.unit_business_flags f
    where f.unit_id = new.unit_id
      and f.business_type = 'daily_rental'
      and f.is_enabled = true
  ) then
    raise exception 'dailyRentalNotEnabledForUnit'
      using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_project_business_mode()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_allows_daily boolean;
  v_allows_lease boolean;
  v_allows_sale boolean;
begin
  select p.allows_daily_rental, p.allows_long_lease, p.allows_sale
  into v_allows_daily, v_allows_lease, v_allows_sale
  from public.units u
  join public.buildings b on b.id = u.building_id
  join public.projects p on p.id = b.project_id
  where u.id = new.unit_id;

  if not found then
    raise exception 'projectBusinessModeNotFound' using errcode = '23503';
  end if;

  if tg_table_name = 'daily_bookings' and not v_allows_daily then
    raise exception 'projectDailyRentalDisabled' using errcode = '23514';
  elsif tg_table_name = 'lease_contracts' and not v_allows_lease then
    raise exception 'projectLongLeaseDisabled' using errcode = '23514';
  elsif tg_table_name = 'sale_contracts' and not v_allows_sale then
    raise exception 'projectSaleDisabled' using errcode = '23514';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_combined_lease_payment_rpc(p_contract_id uuid, p_payment_date date, p_rent_amount_xof numeric, p_property_amount_xof numeric, p_paid_through_date date, p_payment_method text, p_notes text, p_rent_reference_prefix text, p_property_reference_prefix text, p_rent_request_id uuid, p_property_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_rent jsonb;
  v_property jsonb;
begin
  if coalesce(p_rent_amount_xof, 0) <= 0
    or coalesce(p_property_amount_xof, 0) <= 0 then
    raise exception 'combinedAmountsRequired';
  end if;
  if p_paid_through_date is null then raise exception 'paidThroughDateRequired'; end if;
  if p_rent_request_id is null or p_property_request_id is null
    or p_rent_request_id = p_property_request_id then
    raise exception 'distinctRequestIdsRequired';
  end if;

  v_rent := public.record_lease_financial_entry_rpc(
    p_contract_id, 'rent_income', p_payment_date, p_rent_amount_xof,
    p_paid_through_date, p_payment_method, p_notes,
    p_rent_reference_prefix, p_rent_request_id
  );
  v_property := public.record_lease_financial_entry_rpc(
    p_contract_id, 'property_fee_income', p_payment_date, p_property_amount_xof,
    null, p_payment_method, p_notes,
    p_property_reference_prefix, p_property_request_id
  );

  return jsonb_build_object(
    'success', true,
    'rent', v_rent,
    'property_fee', v_property,
    'total_amount_xof', p_rent_amount_xof + p_property_amount_xof
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.record_lease_financial_entry_core_rpc(p_contract_id uuid, p_business_type text, p_payment_date date, p_amount_xof numeric, p_paid_through_date date DEFAULT NULL::date, p_payment_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_reference_prefix text DEFAULT 'LEASE'::text, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_contract public.lease_contracts%rowtype;
  v_unit public.units%rowtype;
  v_source_type text;
  v_direction text;
  v_category text;
  v_label text;
  v_payment_id uuid;
  v_existing_contract_id uuid;
  v_existing_kind text;
  v_reference_no text;
  v_sequence integer;
  v_remaining numeric;
  v_applied numeric;
  v_receivable record;
  v_note text;
begin
  if (select auth.uid()) is null
    or not public.has_app_role('admin', 'finance') then
    raise exception 'leaseFinancePermissionDenied' using errcode = '42501';
  end if;
  if p_request_id is null then raise exception 'requestIdRequired'; end if;
  if p_payment_date is null or coalesce(p_amount_xof, 0) <= 0 then
    raise exception 'invalidLeaseFinancialPayload';
  end if;
  if p_payment_method is null
    or p_payment_method not in ('cash', 'check', 'bank_transfer', 'offset', 'other') then
    raise exception 'paymentMethodRequired';
  end if;
  if p_business_type = 'rent_income' and p_paid_through_date is null then
    raise exception 'paidThroughDateRequired';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_request_id::text, 0));

  select source_id, request_kind
    into v_existing_contract_id, v_existing_kind
  from public.payments
  where request_id = p_request_id;
  if v_existing_contract_id is not null then
    if v_existing_contract_id <> p_contract_id
      or v_existing_kind is distinct from 'lease_financial_entry' then
      raise exception 'requestIdConflict';
    end if;
    select id, receipt_no into v_payment_id, v_reference_no
    from public.payments where request_id = p_request_id;
    return jsonb_build_object(
      'success', true,
      'payment_id', v_payment_id,
      'reference_no', v_reference_no,
      'idempotent', true
    );
  end if;

  select * into v_contract
  from public.lease_contracts
  where id = p_contract_id
  for update;
  if v_contract.id is null then raise exception 'leaseContractNotFound'; end if;

  select * into v_unit
  from public.units
  where id = v_contract.unit_id;

  select source_type, direction, category, label
  into v_source_type, v_direction, v_category, v_label
  from (values
    ('rent_income',         'lease_rent',              'income',        'lease_rent',          '租金收入'),
    ('deposit_income',      'lease_deposit',           'liability_in',  'lease_deposit',       '押金收入'),
    ('agency_income',       'lease_agency_income',     'income',        'lease_agency_income', '中介费收入'),
    ('agency_expense',      'lease_agency_expense',    'expense',       'lease_agency_expense','中介费支出'),
    ('property_fee_income', 'property_fee',            'income',        'property_fee',        '物业费收入'),
    ('furniture_income',    'lease_furniture_income',  'income',        'furniture_fee',       '家具费收入'),
    ('deposit_refund',      'lease_deposit_refund',    'liability_out', 'lease_deposit',       '押金退还'),
    ('other_income',        'lease_other_income',      'income',        'other_income',        '其他收入'),
    ('other_expense',       'lease_other_expense',     'expense',       'other_expense',       '其他支出')
  ) as config(business_type, source_type, direction, category, label)
  where business_type = p_business_type;
  if v_source_type is null then raise exception 'unsupportedLeaseFinancialType'; end if;

  select coalesce(max((regexp_match(receipt_no, '-([0-9]+)$'))[1]::integer), 0) + 1
    into v_sequence
  from public.payments
  where source_id = p_contract_id
    and receipt_no like p_reference_prefix || '-%';
  v_reference_no := p_reference_prefix || '-' || lpad(v_sequence::text, 2, '0');
  v_note := concat_ws('；',
    '业务类型：' || v_label,
    '方式：' || case p_payment_method
      when 'cash' then '现金'
      when 'check' then '支票'
      when 'bank_transfer' then '银行转账'
      when 'offset' then '抵扣/转款'
      else '其他'
    end,
    case when p_paid_through_date is not null then '已缴至：' || p_paid_through_date::text end,
    nullif(trim(coalesce(p_notes, '')), '')
  );

  insert into public.payments(
    customer_id, unit_id, source_type, source_id, payment_date, amount,
    currency, exchange_rate_to_xof, receipt_no, notes, payment_method,
    request_id, request_kind
  ) values (
    v_contract.customer_id, v_contract.unit_id, v_source_type, v_contract.id,
    p_payment_date, p_amount_xof, 'XOF', 1, v_reference_no, v_note,
    p_payment_method, p_request_id, 'lease_financial_entry'
  ) returning id into v_payment_id;

  insert into public.ledger_entries(
    building_id, unit_id, payment_id, entry_date, direction, category,
    amount_xof, description
  ) values (
    v_unit.building_id, v_contract.unit_id, v_payment_id, p_payment_date,
    v_direction, v_category, p_amount_xof,
    v_label || ' 房间' || coalesce(v_unit.unit_no, '未设置') || ' 合同' || v_contract.contract_no
  );

  if p_business_type = 'rent_income' then
    v_remaining := p_amount_xof;
    for v_receivable in
      select id, amount_xof, paid_amount_xof, due_date
      from public.receivables
      where source_type = 'lease_contract'
        and source_id = v_contract.id
        and category = 'lease_rent'
        and status in ('pending', 'partial', 'overdue')
      order by due_date, id
      for update
    loop
      exit when v_remaining <= 0;
      v_applied := least(
        greatest(v_receivable.amount_xof - v_receivable.paid_amount_xof, 0),
        v_remaining
      );
      if v_applied > 0 then
        update public.receivables
        set paid_amount_xof = paid_amount_xof + v_applied,
            status = case
              when paid_amount_xof + v_applied >= amount_xof then 'paid'
              when paid_amount_xof + v_applied > 0 then 'partial'
              when due_date < current_date then 'overdue'
              else 'pending'
            end,
            updated_at = now()
        where id = v_receivable.id;
        v_remaining := v_remaining - v_applied;
      end if;
    end loop;

    if v_contract.paid_through_date is null
      or p_paid_through_date > v_contract.paid_through_date then
      update public.lease_contracts
      set paid_through_date = p_paid_through_date,
          updated_at = now()
      where id = v_contract.id;
    end if;
  elsif p_business_type = 'deposit_income' then
    update public.lease_contracts
    set deposit_received = true,
        deposit_amount_xof = case
          when coalesce(deposit_amount_xof, 0) <= 0 then p_amount_xof
          else deposit_amount_xof
        end,
        updated_at = now()
    where id = v_contract.id;
  end if;

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (
    (select auth.uid()), 'create', 'lease_financial_entry', v_payment_id,
    jsonb_build_object(
      'contract_id', v_contract.id,
      'contract_no', v_contract.contract_no,
      'business_type', p_business_type,
      'source_type', v_source_type,
      'amount_xof', p_amount_xof,
      'paid_through_date', p_paid_through_date,
      'payment_method', p_payment_method,
      'reference_no', v_reference_no,
      'request_id', p_request_id
    )
  );

  return jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'reference_no', v_reference_no,
    'idempotent', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.record_lease_financial_entry_rpc(p_contract_id uuid, p_business_type text, p_payment_date date, p_amount_xof numeric, p_paid_through_date date DEFAULT NULL::date, p_payment_method text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_reference_prefix text DEFAULT 'LEASE'::text, p_request_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if p_contract_id is null or nullif(trim(coalesce(p_reference_prefix, '')), '') is null then
    raise exception 'contractAndReferencePrefixRequired';
  end if;
  -- Serialize visible receipt-number allocation independently from the
  -- idempotency-key lock inside the core implementation.
  perform pg_advisory_xact_lock(
    hashtextextended(p_contract_id::text || ':' || p_reference_prefix, 0)
  );
  return public.record_lease_financial_entry_core_rpc(
    p_contract_id, p_business_type, p_payment_date, p_amount_xof,
    p_paid_through_date, p_payment_method, p_notes,
    p_reference_prefix, p_request_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.record_receivable_payment_rpc(p_receivable_id uuid, p_payment_date date, p_receipt_no text DEFAULT NULL::text, p_request_id uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_receivable public.receivables%rowtype;
  v_payment_id uuid;
  v_amount numeric;
  v_unit_no text;
begin
  if not public.has_app_role('admin', 'finance') then
    raise exception 'financeWritePermissionDenied' using errcode = '42501';
  end if;
  if p_payment_date is null or p_request_id is null then
    raise exception 'invalidPaymentPayload';
  end if;

  select id into v_payment_id from public.payments where request_id = p_request_id;
  if found then
    return jsonb_build_object('success', true, 'payment_id', v_payment_id, 'idempotent', true);
  end if;

  select * into v_receivable
  from public.receivables
  where id = p_receivable_id
  for update;
  if not found or v_receivable.status in ('paid', 'cancelled') then
    raise exception 'receivableNotPayable';
  end if;

  v_amount := greatest(v_receivable.amount_xof - v_receivable.paid_amount_xof, 0);
  if v_amount <= 0 then raise exception 'receivableNotPayable'; end if;
  select unit_no into v_unit_no from public.units where id = v_receivable.unit_id;

  insert into public.payments(
    customer_id, unit_id, source_type, source_id, payment_date, amount,
    currency, exchange_rate_to_xof, receipt_no, request_id
  ) values (
    v_receivable.customer_id, v_receivable.unit_id, v_receivable.source_type,
    v_receivable.source_id, p_payment_date, v_amount, 'XOF', 1,
    nullif(p_receipt_no, ''), p_request_id
  ) returning id into v_payment_id;

  insert into public.ledger_entries(
    building_id, unit_id, payment_id, entry_date, direction, category,
    amount_xof, description
  ) values (
    v_receivable.building_id, v_receivable.unit_id, v_payment_id, p_payment_date,
    'income', v_receivable.category, v_amount,
    trim(v_receivable.title || ' 房间' || coalesce(v_unit_no, '未关联'))
  );

  update public.receivables
  set paid_amount_xof = amount_xof, status = 'paid'
  where id = v_receivable.id;

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'payment', 'receivable', v_receivable.id,
    jsonb_build_object('amount', v_amount, 'date', p_payment_date,
      'receipt_no', nullif(p_receipt_no, ''), 'payment_id', v_payment_id,
      'request_id', p_request_id));

  return jsonb_build_object('success', true, 'payment_id', v_payment_id, 'idempotent', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_sale_payment_rpc(p_contract_id uuid, p_schedule_id uuid, p_amount numeric, p_payment_date date, p_receipt_no text DEFAULT NULL::text, p_request_id uuid DEFAULT gen_random_uuid())
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_schedule public.sale_payment_schedule%rowtype;
  v_contract public.sale_contracts%rowtype;
  v_receivable public.receivables%rowtype;
  v_payment_id uuid;
  v_unpaid numeric;
  v_new_paid numeric;
  v_new_status text;
  v_unit_no text;
  v_building_id uuid;
  v_category text;
begin
  if not public.has_app_role('admin', 'finance') then
    raise exception 'financeWritePermissionDenied' using errcode = '42501';
  end if;
  if coalesce(p_amount, 0) <= 0 or p_payment_date is null or p_request_id is null then
    raise exception 'invalidPaymentPayload';
  end if;

  select id into v_payment_id from public.payments where request_id = p_request_id;
  if found then
    return jsonb_build_object('success', true, 'payment_id', v_payment_id, 'idempotent', true);
  end if;

  select * into v_schedule from public.sale_payment_schedule
  where id = p_schedule_id and sale_contract_id = p_contract_id for update;
  if not found or v_schedule.status in ('paid', 'cancelled') then
    raise exception 'installmentNotPayable';
  end if;

  select * into v_contract from public.sale_contracts
  where id = p_contract_id and status = 'active' for update;
  if not found then raise exception 'saleContractNotActive'; end if;

  v_category := case when v_contract.payment_plan_type = 'lump_sum'
    then 'sale_lump_sum' else 'sale_installment' end;

  select * into v_receivable from public.receivables
  where source_type = 'sale_contract' and source_id = p_contract_id
    and category = v_category and due_date = v_schedule.due_date
    and amount_xof = v_schedule.amount_xof and status <> 'cancelled'
  order by created_at, id limit 1 for update;
  if not found then raise exception 'saleReceivableMissing'; end if;

  v_unpaid := greatest(v_receivable.amount_xof - v_receivable.paid_amount_xof, 0);
  if p_amount > v_unpaid then raise exception 'paymentExceedsOutstanding'; end if;
  v_new_paid := v_receivable.paid_amount_xof + p_amount;
  v_new_status := case
    when v_new_paid >= v_receivable.amount_xof then 'paid'
    when v_receivable.due_date < current_date then 'overdue'
    else 'partial'
  end;
  select unit_no, building_id into v_unit_no, v_building_id
  from public.units where id = v_contract.unit_id;

  insert into public.payments(
    customer_id, unit_id, source_type, source_id, payment_date, amount,
    currency, exchange_rate_to_xof, receipt_no, request_id
  ) values (
    v_contract.customer_id, v_contract.unit_id, 'sale', p_contract_id,
    p_payment_date, p_amount, 'XOF', 1, nullif(p_receipt_no, ''), p_request_id
  ) returning id into v_payment_id;

  insert into public.ledger_entries(
    building_id, unit_id, payment_id, entry_date, direction, category,
    amount_xof, description
  ) values (
    v_building_id, v_contract.unit_id, v_payment_id, p_payment_date, 'income',
    'sale', p_amount,
    format('出售收款 房间%s 第%s期', coalesce(v_unit_no, '未设置'), v_schedule.installment_no)
  );

  update public.receivables
  set paid_amount_xof = v_new_paid, status = v_new_status
  where id = v_receivable.id;
  update public.sale_payment_schedule
  set status = case when v_new_status = 'paid' then 'paid'::public.payment_status
    when v_schedule.due_date < current_date then 'overdue'::public.payment_status
    else 'pending'::public.payment_status end
  where id = v_schedule.id;

  insert into public.audit_logs(actor_id, action, entity_type, entity_id, metadata)
  values (auth.uid(), 'payment', 'sale_contract', p_contract_id,
    jsonb_build_object('amount', p_amount, 'schedule_id', p_schedule_id,
      'receipt_no', nullif(p_receipt_no, ''), 'payment_id', v_payment_id,
      'request_id', p_request_id));

  return jsonb_build_object('success', true, 'payment_id', v_payment_id, 'idempotent', false);
end;
$function$

CREATE OR REPLACE FUNCTION public.renew_lease_rpc(p_contract_id uuid, p_new_end_date date, p_request_id uuid, p_actor jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_contract public.lease_contracts%rowtype; v_old_end_date date;
begin
if auth.uid() is null then raise exception 'leaseRenewalPermissionDenied'; end if;
if p_request_id is null then raise exception 'requestIdRequired'; end if;
if not public.can_execute_operator_action('renew_lease','L3') then raise exception 'leaseRenewalPermissionDenied'; end if;
if p_new_end_date is null then raise exception 'invalidEndDate'; end if;
select * into v_contract from public.lease_contracts where id=p_contract_id and status in ('draft','active') for update;
if not found then raise exception 'leaseContractNotFound'; end if;
v_old_end_date:=v_contract.expected_end_date;
if v_contract.paid_through_date is not null and p_new_end_date<>v_contract.paid_through_date then raise exception 'renewalMustMatchPaidThroughDate'; end if;
if p_new_end_date<v_old_end_date then raise exception 'renewalCannotShortenContract'; end if;
if exists(select 1 from public.audit_logs where actor_id=auth.uid() and action='renew_lease' and metadata->>'request_id'=p_request_id::text) then return jsonb_build_object('success',true,'idempotent',true,'contract_id',p_contract_id,'old_end_date',v_old_end_date,'new_end_date',v_contract.expected_end_date); end if;
update public.lease_contracts set expected_end_date=p_new_end_date,expected_end_confirmed=true,updated_at=now() where id=p_contract_id;
insert into public.audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'renew_lease','lease_contract',p_contract_id,jsonb_build_object('request_id',p_request_id,'old_expected_end_date',v_old_end_date,'new_expected_end_date',p_new_end_date,'paid_through_date',v_contract.paid_through_date,'actor',p_actor));
return jsonb_build_object('success',true,'idempotent',false,'contract_id',p_contract_id,'old_end_date',v_old_end_date,'new_end_date',p_new_end_date);
end;$function$

CREATE OR REPLACE FUNCTION public.set_authenticated_audit_actor()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.role() = 'authenticated' then
    new.actor_id := auth.uid();
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_daily_booking_agent_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.booking_agent_id := coalesce(new.booking_agent_id, new.customer_id);
  if new.booking_agent_id is null then
    raise exception 'dailyBookingAgentRequired';
  end if;
  return new;
end;
$function$

